-- Auction-house help for the unified local beta.
local help
local function createHelp()
  if help or not AuctionHouseFrame or not NokiUnifiedTabs then return end
  help=CreateFrame("Frame",nil,AuctionHouseFrame,"BackdropTemplate");help:Hide();help:SetPoint("TOPLEFT",AuctionHouseFrame,"TOPLEFT",12,-75);help:SetPoint("BOTTOMRIGHT",AuctionHouseFrame,"BOTTOMRIGHT",-12,35);help:SetFrameStrata("DIALOG");help:SetFrameLevel(AuctionHouseFrame:GetFrameLevel()+50);help:SetBackdrop({bgFile="Interface\\Buttons\\WHITE8X8",edgeFile="Interface\\Buttons\\WHITE8X8",edgeSize=1});help:SetBackdropColor(.055,.065,.07,1);help:SetBackdropBorderColor(.25,.3,.28,1)
  local title=help:CreateFontString(nil,"OVERLAY","GameFontNormalLarge");title:SetPoint("TOPLEFT",help,"TOPLEFT",18,-16);title:SetText("NOKI HELP")
  local text=help:CreateFontString(nil,"OVERLAY","GameFontHighlight");text:SetPoint("TOPLEFT",help,"TOPLEFT",18,-52);text:SetPoint("TOPRIGHT",help,"TOPRIGHT",-25,-52);text:SetJustifyH("LEFT");text:SetJustifyV("TOP");text:SetWordWrap(true)
  text:SetText("MARKET\nCompare vendor purchase prices with your latest auction scan. Item Lookup includes items without vendor offers. Match and Under 1c change the profit estimate; they do not post auctions.\n\nCRAFTING\nChoose a profession and filter by known or all recipes. Open a profession window and click Capture recipes to record what you know. Profit uses scanned material prices and a 5% estimated cut.\n\nYOUR AUCTIONS\nShows your listed items, unit and total buyout, the lowest market price per unit, lower-priced units, deposit when available, and time remaining. The market low can include your own listings. A -- deposit means the auction house did not provide it. Use + to compare current, match and undercut totals, vendor price per pack, pack profit, and full-listing profit after the AH cut. The last observed vendor price is preferred; whole-pack purchase costs may include surplus units. Vendor price and availability can change. View opens that item in the normal buy window after competition checks finish. Cancel requires confirmation before requesting one cancellation. A green check means no lower price was found. Equal-price queue position is not included.\n\nMARKET DATA\nFor daily sales estimates, run Noki Trading Updater, or visit devvy.xyz/noki-crafting/, choose your market, copy the import string and press Import data below. Select your own region, ruleset and faction.\n\nSCANS & TOOLTIPS\nA full scan runs at most every 30 minutes by default while the AH is open, or when you press Scan now. Hover over an item for its last scanned auction price; hold Shift for stack value, listed quantity and estimated sales. Listed counts are from the last completed scan.\n\nPrices from AHledger (ahledger.com). Estimates are not confirmed sales; deposits and restrictions can affect profit.")
  local button=CreateFrame("Button",nil,help,"UIPanelButtonTemplate");button:SetSize(130,24);button:SetPoint("TOPRIGHT",help,"TOPRIGHT",-20,-12);button:SetText("Import data");button:SetScript("OnClick",function() NokiUnifiedCore.ShowImport() end)
  NokiUnifiedTabs:CreateTab("NokiUnifiedHelp",help,"Noki Help")
end
local f=CreateFrame("Frame");f:RegisterEvent("AUCTION_HOUSE_SHOW");f:SetScript("OnEvent",function() if C_Timer and C_Timer.After then C_Timer.After(.5,createHelp) else createHelp() end end)
